def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c, v) for r in range(h) for c, v in enumerate(grid[r]) if v not in (0, 8)]
    if not marks:
        raise ValueError('missing color key')
    r0, r1 = min(r for r,c,v in marks), max(r for r,c,v in marks)
    c0, c1 = min(c for r,c,v in marks), max(c for r,c,v in marks)
    key = [[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    # The large 8-valued silhouette is made of square tiles matching the key cells.
    cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    ar, br = min(r for r,c in cells), max(r for r,c in cells)
    ac, bc = min(c for r,c in cells), max(c for r,c in cells)
    bh, bw = br-ar+1, bc-ac+1
    s = None
    for size in range(1, min(bh,bw)+1):
        if bh % size or bw % size or (r1-r0+1) != bh//size or (c1-c0+1) != bw//size:
            continue
        if all(all(grid[r][c] == 8 for r in range(ar+i*size, ar+(i+1)*size)
                   for c in range(ac+j*size, ac+(j+1)*size)) or
               all(grid[r][c] != 8 for r in range(ar+i*size, ar+(i+1)*size)
                   for c in range(ac+j*size, ac+(j+1)*size))
               for i in range(bh//size) for j in range(bw//size)):
            s = size
    if s is None:
        raise ValueError('8 silhouette does not tile to key dimensions')
    # Rotate the key clockwise; each 8-tile takes the corresponding key color.
    rotated = [list(row) for row in zip(*key[::-1])]
    out = [row[:] for row in grid]
    for i in range(len(rotated)):
        for j in range(len(rotated[0])):
            if any(grid[r][c] == 8 for r in range(ar+i*s, ar+(i+1)*s)
                   for c in range(ac+j*s, ac+(j+1)*s)):
                color = rotated[i][j]
                if color == 0:
                    raise ValueError('key and silhouette do not align')
                for r in range(ar+i*s, ar+(i+1)*s):
                    for c in range(ac+j*s, ac+(j+1)*s):
                        out[r][c] = color
    return out
